def isolation_precautions(disease):
    """Maps disease to CDC isolation precaution type."""
    table = {"mrsa": "Contact", "c_diff": "Contact + soap/water handwash",
             "tb": "Airborne (N95, negative pressure)", "measles": "Airborne",
             "flu": "Droplet", "covid": "Airborne + eye protection",
             "norovirus": "Contact", "meningitis": "Droplet (first 24h antibiotics)"}
    return table.get(disease.lower(), "Standard precautions - verify with infection prevention")
print(isolation_precautions("tb"))

